    # Merge lines by SKU and validate
    sku_data: Dict[str, Tuple[int, int]] = {}

    for sku, qty, unit_weight in lines:
        if qty <= 0:
            raise ValueError(f"qty must be positive, got {qty} for {sku}")
        if unit_weight <= 0:
            raise ValueError(f"unit_weight must be positive, got {unit_weight} for {sku}")
        if unit_weight > max_parcel_grams:
            raise ValueError(f"unit weight {unit_weight} for {sku} exceeds max_parcel_grams {max_parcel_grams}")

        if sku in sku_data:
            if sku_data[sku][1] != unit_weight:
                raise ValueError(f"SKU {sku} has inconsistent unit weights")
            sku_data[sku] = (sku_data[sku][0] + qty, unit_weight)
        else:
            sku_data[sku] = (qty, unit_weight)

    # Each merged line is one item for FFD; split only if total weight > capacity
    items_for_ffd: List[Tuple[str, int]] = []

    for sku, (total_qty, unit_weight) in sku_data.items():
        total_weight = total_qty * unit_weight
        if total_weight <= max_parcel_grams:
            items_for_ffd.append((sku, total_weight))
        else:
            max_units = max_parcel_grams // unit_weight
            if max_units == 0:
                raise ValueError(f"unit weight {unit_weight} for {sku} exceeds max_parcel_grams {max_parcel_grams}")
            remaining = total_qty
            while remaining > 0:
                units = min(remaining, max_units)
                items_for_ffd.append((sku, units * unit_weight))
                remaining -= units

    bins = first_fit_decreasing(items_for_ffd, max_parcel_grams)

    parcels: List[Dict[str, int]] = []
    for bin_items in bins:
        parcel: Dict[str, int] = defaultdict(int)
        for sku, weight in bin_items:
            unit_weight = sku_data[sku][1]
            qty = weight // unit_weight
            parcel[sku] += qty
        parcels.append(dict(parcel))

